schemas.schema-1-actors.prisma:
/// Registered member account that serves as the authenticated owner of a
/// private todo workspace.
///
/// This actor model stores the member's email-based sign-in identity and
/// password credential for self-service registration and login. It is the
/// root ownership record for private profile and todo data, while dependent
/// authentication records such as sessions, password reset tokens, and email
/// verification tokens are stored in separate child tables.
///
/// The application supports only self-owned access, so each record
/// represents one private account holder rather than a shared or delegated
/// identity.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model todo_app_members {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Unique email address used as the member's sign-in identity.
  email String

  /// Hashed password credential used to authenticate the member account.
  password_hash String

  /// Whether the member's email ownership has been verified for the account.
  email_verified Boolean

  /// When the member account was created.
  created_at DateTime @db.Timestamptz

  /// When the member account was last updated.
  updated_at DateTime @db.Timestamptz

  /// When the member account was soft-deleted, if applicable.
  deleted_at DateTime? @db.Timestamptz

  //----
  // HAS RELATIONS
  //   - format: (propertyKey targetModel)
  //----
  sessions todo_app_member_sessions[]
  passwordResets todo_app_member_password_resets[]
  emailVerifications todo_app_member_email_verifications[]
  profile todo_app_profiles?
  todos todo_app_todos[]

  //----
  // INDEXES
  //----
  @@unique([email])
}

/// Authenticated session records for member accounts in the private todo
/// application.
///
/// Each record belongs to exactly one {@link todo_app_members} account and
/// captures connection context for a successful sign-in, including client
/// IP, accessed href, referrer, creation time, and expiration time. The
/// table supports account-scoped session tracking and
/// logout/session-lifecycle enforcement without storing unrelated
/// business-domain data.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model todo_app_member_sessions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Owner member account's {@link todo_app_members.id}.
  todo_app_member_id String @db.Uuid

  /// Client IP address recorded for this authenticated session.
  ip String

  /// Requested application href associated with session creation.
  href String

  /// Referrer value observed when the authenticated session was created.
  referrer String

  /// Timestamp when this session record was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when this session expires and is no longer valid for
  /// authenticated access.
  expired_at DateTime @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  member todo_app_members @relation(fields: [todo_app_member_id], references: [id], onDelete: Cascade)

  //----
  // INDEXES
  //----
  @@index([todo_app_member_id, created_at])
}

/// Password reset tokens issued to members for secure account recovery.
///
/// This table stores one-time password reset credentials that belong to a
/// specific {@link todo_app_members} record. Each record represents a reset
/// issuance event with expiration and consumption tracking so the system can
/// validate whether a token is still usable.
///
/// The table is an authentication support entity rather than a standalone
/// business resource. Multiple reset records may exist for the same member
/// over time, enabling auditability and safe recovery workflows without
/// storing redundant member profile data in this table.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model todo_app_member_password_resets {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Belonged member's {@link todo_app_members.id}.
  todo_app_member_id String @db.Uuid

  /// Unique password reset token presented by the member to prove reset
  /// authorization.
  token String

  /// Timestamp when the password reset token was consumed. Null means the
  /// token has not been used yet.
  used_at DateTime? @db.Timestamptz

  /// Timestamp after which the password reset token is no longer valid.
  expired_at DateTime @db.Timestamptz

  /// Timestamp when the password reset record was issued.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the password reset record was last updated.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp for the password reset record.
  deleted_at DateTime? @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  member todo_app_members @relation(fields: [todo_app_member_id], references: [id], onDelete: Cascade)

  //----
  // INDEXES
  //----
  @@unique([token])
  // spellchecker: ignore-next-line
  @@index([todo_app_member_id, created_at], map: "todo_app_member_password_resets_todo_app_member_id_cre_ec559a42")
  @@index([expired_at, used_at])
}

