  /// Required task title shown in the member's private todo lists.
  title String

  /// Optional longer task description entered by the member for additional
  /// details.
  description String?

  /// Optional planned start date and time for the todo.
  start_date DateTime? @db.Timestamptz

  /// Optional due date and time for the todo.
  due_date DateTime? @db.Timestamptz

  /// Whether the todo is currently marked as completed.
  completed Boolean

  /// Timestamp when the todo was most recently marked completed.
  completed_at DateTime? @db.Timestamptz

  /// When the todo was originally created.
  created_at DateTime @db.Timestamptz

  /// When the todo was last updated.
  updated_at DateTime @db.Timestamptz

  /// When the todo was moved to trash. Null means the todo is still in the
  /// active list.
