  id String @id @db.Uuid

  /// Parent todo's {@link todo_app_todos.id}.
  todo_app_todo_id String @db.Uuid

  /// Timestamp when this history entry was created as the recorded edit event.
  created_at DateTime @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  todo todo_app_todos @relation(fields: [todo_app_todo_id], references: [id], onDelete: Cascade)

