    joinBody.ip,
  );
  TestValidator.equals(
    "session href matches join context",
    session.href,
    joinBody.href,
  );
  TestValidator.equals(
    "session referrer matches join context",
    session.referrer,
    joinBody.referrer,
  );
  const expectedMember = {
    id: authorized.id,
