    emptyLimit,
  );
  TestValidator.equals(
    "empty page has no records",
    emptyPage.pagination.records,
    0,
  );
  TestValidator.equals(
    "empty page has no pages",
    emptyPage.pagination.pages,
    0,
  );
  TestValidator.equals("empty page data is empty", emptyPage.data.length, 0);
}

