    completedFalse.title,
    created.title,
  );
  TestValidator.equals(
    "toggle to incomplete preserves description",
    completedFalse.description,
    created.description,
  );
  TestValidator.equals(
    "toggle to incomplete preserves start_date",
    completedFalse.start_date,
    created.start_date,
  );
  TestValidator.equals(
