import { TypedBody, TypedRoute } from "@nestia/core";
import { Controller, Ip } from "@nestjs/common";
import typia from "typia";

import { ITodoAppMember } from "../../../../api/structures/ITodoAppMember";
import { postTodoAppAuthMemberJoin } from "../../../../providers/postTodoAppAuthMemberJoin";
import { postTodoAppAuthMemberLogin } from "../../../../providers/postTodoAppAuthMemberLogin";
import { postTodoAppAuthMemberRefresh } from "../../../../providers/postTodoAppAuthMemberRefresh";

@Controller("/todoApp/auth/member")
export class TodoappAuthMemberController {
  /**
   * This operation registers a new member account for the private todo application by creating the root ownership record in `todo_app_members`. The loaded requirements define the member as an email-based account owner who uses the application for personal todo management, and the registration flow explicitly states that a person can register by providing an email address and a password. A successful registration creates the private account space that will own the member's profile, todos, and todo edit history.
   *
   * The endpoint creates the member actor's own authenticated entry point into the service. The underlying member schema confirms that the sign-in identity is stored in the `email` column and the credential is persisted as `password_hash`, while `email_verified` tracks whether ownership of the email address has been confirmed. The operation therefore validates the required registration fields, enforces uniqueness of the `email` value, and creates the member row with auditable timestamps such as `created_at` and `updated_at`.
   *
   * The schema also shows that authentication support records are separated into child tables. Because `todo_app_member_sessions` stores the account-scoped session context with `ip`, `href`, `referrer`, `created_at`, and `expired_at`, the registration flow can complete by issuing an authenticated session and returning an authorized response. In addition, `todo_app_member_email_verifications` stores verification `token` values together with `expired_at`, `used_at`, and `revoked_at`, so implementations may issue an email verification artifact at registration time when email ownership confirmation is part of the security workflow.
   *
   * From a business rule perspective, this operation must reject requests when the email address or password is not provided, and it must reject requests when the email address is already associated with an existing account. Those requirements come directly from the registration section and align with the unique constraint on `todo_app_members.email`. The operation must not create duplicate ownership roots for the same email identity.
   *
   * This operation is typically the first authentication entry point for a new member. After registration succeeds, the member can continue using the returned authorization payload directly or use the login endpoint later with the same email and password. If verification is required, related verification endpoints may be used to confirm email ownership, but no prerequisite API call is required before this registration request itself.
   *
   * @setHeader token.access Authorization
   *
   * @param connection
   * @param body Registration credentials for creating a member account.
   * @x-autobe-authorization-type join
   * @x-autobe-authorization-actor member
   * @x-autobe-specification Implement member registration as a public authentication endpoint. Validate that the request body includes the email identity and password required by the registration requirements. Normalize the email consistently for uniqueness checks, query `todo_app_members` by email, and reject the request when an active account with the same email already exists. Also reject requests with missing required credential values.
   *
   * Within a transaction, create a new `todo_app_members` row with a generated UUID, the submitted email, a securely hashed password stored in `password_hash`, `email_verified` initialized according to the product policy, and current timestamps for `created_at` and `updated_at`. Immediately create an authenticated session record in `todo_app_member_sessions` using connection context such as client IP, href, referrer, and an expiration timestamp so the authorized response can be issued without a separate login round-trip.
   *
   * If the implementation policy requires email ownership confirmation, create a new `todo_app_member_email_verifications` row with a unique token, expiration timestamp, issuance timestamps, and null `used_at` and `revoked_at`. Return `ITodoAppMember.IAuthorized` containing the issued access and refresh credentials for the newly registered member. Exclude member rows whose `deleted_at` indicates the account has been deleted from any successful registration conflict-resolution logic unless the product explicitly restores them through a separate workflow.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("join")
  public async join(
    @Ip()
    ip: string,
    @TypedBody()
    body: ITodoAppMember.IJoin,
  ): Promise<ITodoAppMember.IAuthorized> {
    try {
      return await postTodoAppAuthMemberJoin({
        ip,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * This operation authenticates an existing member by validating the email-based identity and password credential stored on `todo_app_members`. The requirements explicitly say that after registration succeeds, the member can use the same email address and password to sign in. That makes login a core authorization operation for the single member actor in this private todo application.
   *
   * The underlying member schema provides the exact persistence model for this flow. The `email` column is the unique sign-in identity, `password_hash` stores the hashed credential, and `deleted_at` indicates that an account may no longer be active for authentication. The operation therefore locates the member by `email`, verifies the submitted password against `password_hash`, and rejects invalid or unavailable accounts. Because the application is organized around self-owned private account spaces, a successful login restores access only to the authenticated member's own account data.
   *
   * A successful login is also tied to the session support schema. The `todo_app_member_sessions` table documents an authenticated session record that belongs to exactly one member account and captures connection context such as `ip`, `href`, `referrer`, `created_at`, and `expired_at`. The login implementation should create such a session record so token issuance is grounded in server-side session lifecycle tracking and refresh validation can later depend on an existing session context.
   *
   * The `email_verified` column on `todo_app_members` may influence downstream authorization policy because it records whether ownership of the sign-in email has been verified. This endpoint should rely only on confirmed schema state and may incorporate that value into authorization outcomes or claims if the product policy requires it. It must not assume additional factors such as MFA, login throttling counters, or username aliases because those fields are not present in the loaded schema.
   *
   * This operation works together with registration and refresh. Registration creates the account, login authenticates an existing one, and refresh renews authorization using session-linked tokens. No separate prerequisite API is required before login, and no logout endpoint is documented here because the authorization design explicitly excludes logout as a generated API operation.
   *
   * @setHeader token.access Authorization
   *
   * @param connection
   * @param body Login credentials for authenticating an existing member account.
